export function reportedForm() { return `<!doctype html><h1>Apply for this job</h1><style>label,.field{display:block;margin:15px}input,select{padding:6px}</style><form onsubmit="event.preventDefault();window.__submissions++">
<label>First Name<input id=first></label><label>Last Name<input id=last></label><label>Email<input id=email type=email></label>
<div class=field><label for=mobile>Mobile Phone</label><select id=prefix><option value="">Select</option><option value=91>India (+91)</option><option value=1>United States (+1)</option></select><input id=mobile type=tel maxlength=10></div>
<label>Current Location<input id=location></label><label>LinkedIn Profile<input id=linkedin type=url></label>
<label>Specialisation (Primary specialisation Ex: Computer Science and Engineering (CSE) and Information Technology (IT).)<input id=major></label>
<label>College Name<input id=college></label><label>10th Percentage (On a scale of 100)<select id=tenth><option value="">Select an option</option><option>80–90%</option><option>90–100%</option></select></label>
<label>UG/PG Percentage (On a scale of 100)<select id=percent><option value="">Select an option</option><option>80–90%</option><option>90–100%</option></select></label>
<label>Choose your preferred language for the online MCQ test<input id=language></label><label>Attach Video Introduction link with access permission<input id=video type=url></label>
<label><input id=consent type=checkbox>By applying you accept data processing terms and give consent</label><label>Captcha<input id=captcha></label><button type=submit>Apply Now</button></form><script>window.__submissions=0;</script>`; }
export function reportedKekaForm() {
  const phone=`<div class="validation"><label for=phone>Mobile Phone <span>*</span></label><label for=phone></label><div class="row no-gutters"><div class=col-3><select class=select2-hidden-accessible name="mobilePhone.countryCode" id="mobilePhone.countryCode" aria-hidden=true tabindex=-1 style="display:none"><option value=""></option><option value="+93">+93</option><option value="+91">+91</option><option value="+1">+1</option></select><span class="select2 select2-container"><span class=selection><span class="select2-selection select2-selection--single" role=combobox tabindex=0 aria-labelledby=select2-mobilePhonecountryCode-container><span class=select2-selection__rendered id=select2-mobilePhonecountryCode-container role=textbox aria-readonly=true>Select</span></span></span></span></div><div class=col><input id="mobilePhone.number" name="mobilePhone.number" type=text maxlength=13 minlength=4 placeholder="Mobile Phone" required></div></div><label id=ph-error for=phone class=error></label></div><script>document.getElementById('mobilePhone.countryCode').addEventListener('change',()=>{const select=document.getElementById('mobilePhone.countryCode');document.getElementById('select2-mobilePhonecountryCode-container').textContent=select.value?select.selectedOptions[0].text:'Select';});</script>`;
  return reportedForm().replace(/<div class=field>[\s\S]*?<\/div>/,phone);
}
